import { isBooleanJsonSchema } from '@scalar/openapi-types/helpers';

import { resolveExampleRefs } from '../resolvers';
import type {
  ContextSpec,
  OpenApiPrimitiveSchemaType,
  OpenApiSchemaObject,
  ScalarValue,
} from '../types';
import { getComponentBaseNames, sanitize, toJsLiteral } from '../utils';
import { isNullOnlyEnum, isStringLikeSchema } from '../utils/assertion';
import { getFormDataFieldFileType } from '../utils/content-type';
import { getArray } from './array';
import { combineSchemas } from './combine';
import type { FormDataContext } from './object';
import { getObject } from './object';

/** Bridge type for enum values extracted from OpenAPI schemas infected by AnyOtherAttribute */
type SchemaEnumValue = string | number | boolean | null;

/**
 * Returns true when a schema describes a raw binary string scalar — i.e. one
 * that getScalar's `case 'string':` branch would coerce to `Blob` outside a
 * url-encoded context (see the formDataContext.urlEncoded gate below). Shared
 * with resolveValue so the component-`$ref` urlEncoded short-circuit and the
 * inline scalar path stay in lockstep when new binary shapes are added
 * (#1624 / #3395 / #2410).
 *
 * Accepts OAS 3.1 nullable unions (`type: ['string', 'null']`) since getScalar
 * normalizes those into `case 'string':` before invoking this predicate.
 */
export function isBinaryScalarSchema(schema: OpenApiSchemaObject): boolean {
  if (isBooleanJsonSchema(schema) || !isStringLikeSchema(schema)) {
    return false;
  }
  if (schema.format === 'binary') {
    return true;
  }
  // The @scalar/openapi-parser upgrader rewrites format: binary to
  // contentMediaType: application/octet-stream during Swagger 2.0 / OAS 3.0 →
  // OAS 3.1 upgrades; treat the upgraded shape the same. A non-empty
  // contentEncoding signals an encoded string payload (e.g. base64), not raw
  // binary.
  const contentMediaType = schema.contentMediaType;
  const contentEncoding = schema.contentEncoding;
  return contentMediaType === 'application/octet-stream' && !contentEncoding;
}

interface BinaryTypeNames {
  blob: string;
  file: string;
}

// Keyed by spec, then by the component naming overrides, since one spec can be
// generated by several outputs whose prefixes/suffixes decide the collision.
const binaryTypeNamesCache = new WeakMap<
  object,
  WeakMap<object, BinaryTypeNames>
>();
const noComponentOverrides = {};

/**
 * Returns the type names to emit for binary scalars. A component named `Blob`
 * or `File` (e.g. a `File` metadata schema) is emitted as a same-named
 * interface that shadows the DOM global wherever both live in one module, so
 * those globals are qualified with `globalThis.` in that case (#4259).
 */
function getBinaryTypeNames(context: ContextSpec): BinaryTypeNames {
  // Hand-built contexts (tests, programmatic callers) may omit these.
  const overrides: Partial<
    Record<
      'schemas' | 'responses' | 'requestBodies' | 'parameters',
      { prefix?: string; suffix?: string }
    >
  > =
    (context.output.override as Partial<typeof context.output.override>)
      .components ?? noComponentOverrides;

  let specCache = binaryTypeNamesCache.get(context.spec);
  if (!specCache) {
    specCache = new WeakMap();
    binaryTypeNamesCache.set(context.spec, specCache);
  }
  const cached = specCache.get(overrides);
  if (cached) {
    return cached;
  }

  const { components } = context.spec;
  const sections = [
    [components?.schemas, overrides.schemas],
    [components?.responses, overrides.responses],
    [components?.requestBodies, overrides.requestBodies],
    [components?.parameters, overrides.parameters],
  ] as const;

  const componentNames = new Set<string>();
  for (const [section, { prefix = '', suffix = '' } = {}] of sections) {
    for (const baseName of getComponentBaseNames(section).values()) {
      componentNames.add(
        sanitize(`${prefix}${baseName}${suffix}`, {
          underscore: '_',
          whitespace: '_',
          dash: true,
          es5keyword: true,
          es5IdentifierName: true,
        }),
      );
    }
  }

  const qualify = (name: string) =>
    componentNames.has(name) ? `globalThis.${name}` : name;
  const names = { blob: qualify('Blob'), file: qualify('File') };
  specCache.set(overrides, names);
  return names;
}

interface GetScalarOptions {
  item: OpenApiSchemaObject;
  name?: string;
  context: ContextSpec;
  formDataContext?: FormDataContext;
}

/**
 * Return the typescript equivalent of open-api data type
 *
 * @param item
 * @ref https://github.com/OAI/OpenAPI-Specification/blob/main/versions/3.1.1.md#data-types
 */
const booleanSchemaScalar = (value: 'unknown' | 'never'): ScalarValue => ({
  value,
  isEnum: false,
  hasReadonlyProps: false,
  type: 'unknown',
  imports: [],
  schemas: [],
  isRef: false,
  dependencies: [],
});

export function getScalar({
  item,
  name,
  context,
  formDataContext,
}: GetScalarOptions): ScalarValue {
  if (item === true) {
    return booleanSchemaScalar('unknown');
  }
  if (item === false) {
    return booleanSchemaScalar('never');
  }

  // Bridge assertions: extract typed values from AnyOtherAttribute-infected schema
  const schemaEnum = item.enum as SchemaEnumValue[] | undefined;
  const schemaType = item.type as
    | OpenApiPrimitiveSchemaType
    | OpenApiPrimitiveSchemaType[]
    | undefined;
  const schemaReadOnly = item.readOnly;
  const schemaExample = item.example as unknown;
  const schemaExamples = item.examples as Parameters<
    typeof resolveExampleRefs
  >[0];
  const schemaConst = item.const as unknown;
  const schemaFormat = item.format as string | undefined;

  const nullable =
    Array.isArray(schemaType) && schemaType.includes('null') ? ' | null' : '';

  const enumItems = schemaEnum?.filter(
    (enumItem): enumItem is Exclude<SchemaEnumValue, null> => enumItem !== null,
  );

  let itemType:
    | OpenApiPrimitiveSchemaType
    | OpenApiPrimitiveSchemaType[]
    | undefined = schemaType;
  if (!itemType && item.items) {
    item.type = 'array';
    itemType = 'array';
  }
  if (Array.isArray(schemaType) && schemaType.includes('null')) {
    const typesWithoutNull = schemaType.filter(
      (x): x is OpenApiPrimitiveSchemaType => x !== 'null',
    );
    itemType =
      typesWithoutNull.length === 1 ? typesWithoutNull[0] : typesWithoutNull;
  }
  if (isNullOnlyEnum(item)) {
    itemType = 'null';
  }

  switch (itemType) {
    case 'number':
    case 'integer': {
      let value =
        context.output.override.useBigInt &&
        (schemaFormat === 'int64' || schemaFormat === 'uint64')
          ? 'bigint'
          : 'number';
      let isEnum = false;

      if (enumItems) {
        value = enumItems.map((enumItem) => toJsLiteral(enumItem)).join(' | ');
        isEnum = true;
      }

      value += nullable;

      // Keep the type value a string. Numeric `const` values (common from
      // FastAPI/Pydantic Literal[int] fields that also emit `enum`) must not
      // replace the union with a raw number, or getTypeConstEnum crashes on
      // `value.endsWith(...)` (#3758).
      if (schemaConst !== undefined) {
        value = `${toJsLiteral(schemaConst)}${nullable}`;
      }

      return {
        value,
        isEnum,
        type: 'number',
        schemas: [],
        imports: [],
        isRef: false,
        hasReadonlyProps: schemaReadOnly ?? false,
        dependencies: [],
        example: schemaExample,
        examples: resolveExampleRefs(schemaExamples, context),
      };
    }

    case 'boolean': {
      let value = 'boolean';

      if (
        enumItems &&
        !(enumItems.includes(true) && enumItems.includes(false))
      ) {
        value = enumItems.map((enumItem) => toJsLiteral(enumItem)).join(' | ');
      }

      value += nullable;

      // Same string-coercion as integer/number so const never becomes a
      // non-string type-value for downstream enum helpers (#3758).
      if (schemaConst !== undefined) {
        value = `${toJsLiteral(schemaConst)}${nullable}`;
      }

      return {
        value: value,
        type: 'boolean',
        isEnum: false,
        schemas: [],
        imports: [],
        isRef: false,
        hasReadonlyProps: schemaReadOnly ?? false,
        dependencies: [],
        example: schemaExample,
        examples: resolveExampleRefs(schemaExamples, context),
      };
    }

    case 'array': {
      const { value, ...rest } = getArray({
        schema: item,
        name,
        context,
        formDataContext,
      });
      return {
        value: value + nullable,
        ...rest,
        dependencies: rest.dependencies,
      };
    }

    case 'string': {
      let value = 'string';
      let isEnum = false;

      if (enumItems) {
        value = enumItems
          .map((enumItem) => toJsLiteral(enumItem))
          .filter(Boolean)
          .join(` | `);

        isEnum = true;
      }

      // application/x-www-form-urlencoded bodies are built with URLSearchParams,
      // whose values are always strings. Skip Blob/file coercion so file/binary
      // fields stay `string`; enum unions computed above are left intact (#1624).
      if (!formDataContext?.urlEncoded) {
        const { blob, file } = getBinaryTypeNames(context);
        if (schemaFormat === 'binary') {
          // In multipart/form-data context, accept both Blob and File so the
          // filename is preserved in the Content-Disposition header (#3662).
          // Blob | File is wider than the original Blob, so existing callers
          // keep compiling (#3915).
          value = formDataContext ? `${blob} | ${file}` : blob;
        } else if (formDataContext?.atPart) {
          const fileType = getFormDataFieldFileType(
            item,
            formDataContext.partContentType,
          );
          if (fileType) {
            value =
              fileType === 'binary'
                ? `${blob} | ${file}`
                : `${blob} | ${file} | string`;
          }
        } else if (isBinaryScalarSchema(item)) {
          // The previous arm caught format: binary directly; this matches the
          // OAS 3.1 contentMediaType: application/octet-stream variant via the
          // shared predicate so any future binary shapes added there flow
          // through here too (#2410). In multipart context accept both Blob and
          // File so existing callers keep compiling (#3915).
          value = formDataContext ? `${blob} | ${file}` : blob;
        }
      }

      if (
        context.output.override.useDates &&
        (schemaFormat === 'date' || schemaFormat === 'date-time')
      ) {
        value = 'Date';
      }

      value += nullable;

      // Presence, not truthiness: `const: ''` / `0` / `false` are all real
      // constants, and a truthiness check dropped them back to the wide type.
      // The nullable suffix has to be re-applied because this overwrites the
      // value assigned above, which is how the number and boolean branches do
      // it too.
      if (schemaConst !== undefined) {
        // A non-string `const` under `type: string` is another mismatch; the
        // helper renders whichever literal the value actually is. Previously
        // this reached the string escaper with a non-string and threw.
        value = `${toJsLiteral(schemaConst)}${nullable}`;
      }

      return {
        value: value,
        isEnum,
        type: 'string',
        imports: [],
        schemas: [],
        isRef: false,
        hasReadonlyProps: schemaReadOnly ?? false,
        dependencies: [],
        example: schemaExample,
        examples: resolveExampleRefs(schemaExamples, context),
      };
    }

    case 'null': {
      // Some OAS 3.1 generators emit a nullable composition in the
      // non-canonical form `{ type: 'null', allOf|oneOf|anyOf: [...] }`
      // (e.g. Swashbuckle with UseAllOfToExtendReferenceSchemas; passed
      // through by @scalar/openapi-upgrader) rather than the canonical
      // `{ anyOf: [...], type: 'null' }` member form. Treat the composition as
      // the value and `null` as a union member so this yields `T | null`
      // instead of collapsing to `null` and dropping the refs.
      const itemAllOf = item.allOf as unknown[] | undefined;
      const itemOneOf = item.oneOf as unknown[] | undefined;
      const itemAnyOf = item.anyOf as unknown[] | undefined;
      let separator: 'allOf' | 'oneOf' | 'anyOf' | undefined;
      if (itemAllOf?.length) {
        separator = 'allOf';
      } else if (itemOneOf?.length) {
        separator = 'oneOf';
      } else if (itemAnyOf?.length) {
        separator = 'anyOf';
      }
      if (separator) {
        // Drop the consumed `type: 'null'` before delegating: its nullability
        // is carried by `nullable` below, and leaving it on the schema makes
        // combineSchemas' merged-properties recursion re-enter this `case` and
        // collapse the object part back to `null`.
        const schemaWithoutNull = Object.fromEntries(
          Object.entries(item as Record<string, unknown>).filter(
            ([key]) => key !== 'type',
          ),
        ) as OpenApiSchemaObject;
        return combineSchemas({
          schema: schemaWithoutNull,
          name,
          separator,
          context,
          nullable: nullable || ' | null',
          formDataContext,
        });
      }

      return {
        value: 'null',
        isEnum: false,
        type: 'null',
        imports: [],
        schemas: [],
        isRef: false,
        hasReadonlyProps: schemaReadOnly ?? false,
        dependencies: [],
      };
    }

    default: {
      if (Array.isArray(itemType)) {
        const anyOfVariants = itemType.map((type) =>
          Object.assign({}, item, { type }),
        ) as OpenApiSchemaObject[];
        return combineSchemas({
          schema: { anyOf: anyOfVariants } as OpenApiSchemaObject,
          name,
          separator: 'anyOf',
          context,
          nullable,
        });
      }

      if (enumItems) {
        const value = enumItems
          .map((enumItem) => toJsLiteral(enumItem))
          .filter(Boolean)
          .join(` | `);

        return {
          value: value + nullable,
          isEnum: true,
          type: 'string',
          imports: [],
          schemas: [],
          isRef: false,
          hasReadonlyProps: schemaReadOnly ?? false,
          dependencies: [],
          example: schemaExample,
          examples: resolveExampleRefs(schemaExamples, context),
        };
      }

      // Determine if we should pass form-data context:
      // - atPart: false -> always pass (navigating to properties)
      // - atPart: true + combiner -> pass (combiner members are still the same part)
      // - atPart: true + plain object -> don't pass (nested properties are JSON)
      const hasCombiners = (item.allOf ?? item.anyOf ?? item.oneOf) as
        | unknown[]
        | undefined;
      const shouldPassContext =
        formDataContext?.atPart === false ||
        (formDataContext?.atPart && hasCombiners);

      const { value, ...rest } = getObject({
        item,
        name,
        context,
        nullable,
        formDataContext: shouldPassContext ? formDataContext : undefined,
      });
      return { value: value, ...rest };
    }
  }
}
