import {
  isBooleanJsonSchema,
  isNullSchema,
} from '@scalar/openapi-types/helpers';
import { keyword } from 'esutils';

import { isPrimitiveResponseSchema } from '../generators/runtime-validation';
import { resolveObject } from '../resolvers/object';
import { resolveExampleRefs, resolveRef } from '../resolvers/ref';
import {
  type ContextSpec,
  FormDataArrayHandling,
  type GeneratorImport,
  type GetterResponse,
  type OpenApiEncodingObject,
  type OpenApiMediaTypeObject,
  type OpenApiReferenceObject,
  type OpenApiRequestBodyObject,
  type OpenApiResponseObject,
  type OpenApiSchemaObject,
  type ResReqTypesValue,
} from '../types';
import { uniqueBy } from '../utils';
import { camel, isInlineSchema, isSchemaNullable, sanitize } from '../utils';
import { pascal, conventionName } from '../utils/case';
import {
  getFormDataFieldFileType,
  isBinaryContentType,
} from '../utils/content-type';
import { getNumberWord, jsStringLiteralEscape } from '../utils/string';
import { getKey, getPropertyNameCollisionKeys } from './keys';
import type { FormDataContext } from './object';

const getSchemaType = (s: OpenApiSchemaObject) =>
  isBooleanJsonSchema(s)
    ? undefined
    : (s.type as string | string[] | undefined);
const getSchemaCombined = (s: OpenApiSchemaObject) =>
  isBooleanJsonSchema(s) ? undefined : (s.oneOf ?? s.anyOf ?? s.allOf);
const getSchemaOneOf = (s: OpenApiSchemaObject) =>
  isBooleanJsonSchema(s) ? undefined : s.oneOf;
const getSchemaAnyOf = (s: OpenApiSchemaObject) =>
  isBooleanJsonSchema(s) ? undefined : s.anyOf;
const getSchemaItems = (s: OpenApiSchemaObject) =>
  isBooleanJsonSchema(s) ? undefined : s.items;
const getSchemaRequired = (s: OpenApiSchemaObject) =>
  isBooleanJsonSchema(s) ? undefined : s.required;
const getSchemaProperties = (s: OpenApiSchemaObject) =>
  isBooleanJsonSchema(s) ? undefined : s.properties;
const resolveSchemaRef = (
  schema: OpenApiSchemaObject | OpenApiReferenceObject,
  context: ContextSpec,
) =>
  resolveRef(schema as OpenApiReferenceObject, context) as {
    schema: OpenApiSchemaObject;
    imports: GeneratorImport[];
  };
const resolveResponseOrRequestRef = (
  schema: OpenApiReferenceObject,
  context: ContextSpec,
) =>
  resolveRef(schema, context) as {
    schema: OpenApiResponseObject | OpenApiRequestBodyObject;
    imports: GeneratorImport[];
  };

const formDataContentTypes = new Set(['multipart/form-data']);

const formUrlEncodedContentTypes = new Set([
  'application/x-www-form-urlencoded',
]);

interface GetResReqContentTypesOptions {
  mediaType: OpenApiMediaTypeObject;
  propName?: string;
  context: ContextSpec;
  isFormData?: boolean;
  contentType: string;
  generatePrimitiveSchema?: boolean;
}

function getResReqContentTypes({
  mediaType,
  propName,
  context,
  isFormData,
  contentType,
  generatePrimitiveSchema,
}: GetResReqContentTypesOptions) {
  // `false` is a JSON Schema that admits nothing (`never`). Only a missing
  // schema means this media type has no type to emit.
  // oxlint-disable-next-line typescript/no-unnecessary-condition
  if (mediaType.schema === undefined || mediaType.schema === null) {
    return;
  }

  // For form bodies, pass context that tracks encoding for file type
  // detection. url-encoded bodies additionally flag `urlEncoded` so file/binary
  // fields are typed as `string` rather than `Blob` (#1624).
  const isFormUrlEncoded = formUrlEncodedContentTypes.has(contentType);
  const formDataContext: FormDataContext | undefined = isFormData
    ? { atPart: false, encoding: mediaType.encoding ?? {} }
    : isFormUrlEncoded
      ? { atPart: false, encoding: mediaType.encoding ?? {}, urlEncoded: true }
      : undefined;

  const resolvedObject = resolveObject({
    schema: mediaType.schema,
    propName,
    context,
    formDataContext,
  });

  // Known binary content type → Blob (overrides schema)
  // This ensures correct responseType ('blob') even when schema lacks format: binary.
  if (!isFormData && isBinaryContentType(contentType)) {
    return {
      ...resolvedObject,
      value: 'Blob',
    };
  }

  if (
    generatePrimitiveSchema &&
    propName &&
    isPrimitiveResponseSchema(mediaType.schema) &&
    resolvedObject.value !== 'Blob'
  ) {
    // Use the normal schema writers, so Zod version/variant, integer checks,
    // formats, enums and nullability follow the same rules as components.
    const existingSchema = resolvedObject.schemas.find(
      ({ name }) => name === propName,
    );
    return {
      ...resolvedObject,
      value: propName,
      imports: [{ name: propName }],
      schemas: [
        ...resolvedObject.schemas.filter(({ name }) => name !== propName),
        {
          name: propName,
          model:
            existingSchema?.model ??
            `export type ${propName} = ${resolvedObject.value};\n`,
          imports: existingSchema?.imports ?? resolvedObject.imports,
          dependencies:
            existingSchema?.dependencies ?? resolvedObject.dependencies,
          kind: existingSchema?.kind ?? ('schema' as const),
          schema: resolvedObject.originalSchema,
        },
      ],
    };
  }

  return resolvedObject;
}

export function getResReqTypes(
  responsesOrRequests: [
    string,
    OpenApiReferenceObject | OpenApiResponseObject | OpenApiRequestBodyObject,
  ][],
  name: string,
  context: ContextSpec,
  defaultType = 'unknown',
  uniqueKey: (
    item: ResReqTypesValue,
    index: number,
    data: ResReqTypesValue[],
  ) => unknown = (item) => item.value,
  generatePrimitiveSchemas = false,
): ResReqTypesValue[] {
  const typesArray = responsesOrRequests
    .filter(([, res]) => Boolean(res))
    .map(([key, res]) => {
      if (!isInlineSchema(res)) {
        const {
          schema: bodySchema,
          imports: [{ name, schemaName }],
        } = resolveResponseOrRequestRef(res, context);

        const firstEntry = Object.entries(bodySchema.content ?? {}).at(0);

        if (!firstEntry) {
          return [
            {
              value: name,
              imports: [{ name, schemaName }],
              schemas: [],
              type: 'unknown',
              isEnum: false,
              isRef: true,
              hasReadonlyProps: false,
              dependencies: [name],
              originalSchema: undefined,
              example: undefined,
              examples: undefined,
              key,
              contentType: '',
            },
          ] as ResReqTypesValue[];
        }

        const [contentType, mediaType] = firstEntry;

        const isFormData = formDataContentTypes.has(contentType);
        const isFormUrlEncoded = formUrlEncodedContentTypes.has(contentType);

        if ((!isFormData && !isFormUrlEncoded) || !mediaType.schema) {
          return [
            {
              value: name,
              imports: [{ name, schemaName }],
              schemas: [],
              type: 'unknown',
              isEnum: false,
              isRef: true,
              hasReadonlyProps: false,
              dependencies: [name],
              originalSchema: mediaType.schema,
              example: mediaType.example,
              examples: resolveExampleRefs(
                mediaType.examples as
                  | Record<string, OpenApiReferenceObject | { value?: unknown }>
                  | undefined,
                context,
              ),
              key,
              contentType,
            },
          ] as ResReqTypesValue[];
        }

        // OpenAPI defaults requestBody.required to false when the key is absent.
        const isRequestBodyOptional =
          !('required' in bodySchema) || bodySchema.required !== true;

        const formData = isFormData
          ? getSchemaFormDataAndUrlEncoded({
              name,
              schemaObject: mediaType.schema,
              context,
              isRequestBodyOptional,
              isRef: true,
              encoding: mediaType.encoding,
            })
          : undefined;

        const formUrlEncoded = isFormUrlEncoded
          ? getSchemaFormDataAndUrlEncoded({
              name,
              schemaObject: mediaType.schema,
              context,
              isRequestBodyOptional,
              isUrlEncoded: true,
              isRef: true,
              encoding: mediaType.encoding,
            })
          : undefined;

        const additionalImports = getFormDataAdditionalImports({
          schemaObject: mediaType.schema,
          context,
        });

        return [
          {
            value: name,
            imports: [{ name, schemaName }, ...additionalImports],
            schemas: [],
            type: 'unknown',
            isEnum: false,
            hasReadonlyProps: false,
            dependencies: [name],
            formData,
            formUrlEncoded,
            isRef: true,
            originalSchema: mediaType.schema,
            example: mediaType.example,
            examples: resolveExampleRefs(mediaType.examples, context),
            key,
            contentType,
          },
        ] as ResReqTypesValue[];
      }

      if (res.content) {
        const contents = Object.entries(res.content).map(
          ([contentType, mediaType], index, arr) => {
            let propName = key
              ? sanitize(pascal(name) + pascal(key), {
                  underscore: '_',
                  whitespace: '_',
                  dash: true,
                  es5keyword: true,
                  es5IdentifierName: true,
                })
              : undefined;

            if (propName && arr.length > 1) {
              propName = propName + pascal(getNumberWord(index + 1));
            }

            const isFormData = formDataContentTypes.has(contentType);
            const isFormUrlEncoded =
              formUrlEncodedContentTypes.has(contentType);

            // When schema is a $ref, use schema name for consistent param naming
            let effectivePropName = propName;
            if (mediaType.schema && !isInlineSchema(mediaType.schema)) {
              const { imports } = resolveSchemaRef(mediaType.schema, context);
              if (imports[0]?.name) {
                effectivePropName = imports[0].name;
              }
            } else if ((isFormData || isFormUrlEncoded) && mediaType.schema) {
              // For form-data and url-encoded, the param name is also the
              // runtime variable iterated by the FormData/URLSearchParams code.
              // Derive it from the inner DTO names so it matches the function
              // parameter (#3242). Scoped to these content types: forcing the
              // schema name elsewhere aliases the import to `Foo as __Foo` in
              // split mode and broke the MSW mock filter (#3269).
              const combinedRefs =
                getSchemaOneOf(mediaType.schema) ??
                getSchemaAnyOf(mediaType.schema);
              if (combinedRefs) {
                const names: string[] = [];
                for (const ref of combinedRefs) {
                  if (isInlineSchema(ref)) continue;
                  const refName = resolveSchemaRef(ref, context).imports[0]
                    ?.name;
                  if (refName) {
                    names.push(refName);
                  }
                }
                if (names.length > 0) {
                  effectivePropName = names.join('');
                }
              }
            }

            const resolvedValue = getResReqContentTypes({
              mediaType,
              propName: effectivePropName,
              context,
              isFormData,
              contentType,
              generatePrimitiveSchema:
                generatePrimitiveSchemas &&
                key.startsWith('2') &&
                contentType.includes('json') &&
                !contentType.includes('ndjson') &&
                !contentType.includes('nd-json'),
            });

            if (!resolvedValue) {
              // openapi spec 3.1 allows describing binary responses with only a content type
              if (isBinaryContentType(contentType)) {
                return {
                  value: 'Blob',
                  imports: [],
                  schemas: [],
                  type: 'Blob',
                  isEnum: false,
                  key,
                  isRef: false,
                  hasReadonlyProps: false,
                  contentType,
                };
              }

              return;
            }

            if (
              (!isFormData && !isFormUrlEncoded) ||
              !effectivePropName ||
              !mediaType.schema
            ) {
              return {
                ...resolvedValue,
                imports: resolvedValue.imports,
                dependencies: resolvedValue.dependencies,
                contentType,
                example: mediaType.example,
                examples: resolveExampleRefs(mediaType.examples, context),
              };
            }

            const formData = isFormData
              ? getSchemaFormDataAndUrlEncoded({
                  name: effectivePropName,
                  schemaObject: mediaType.schema,
                  context,
                  isRequestBodyOptional:
                    !('required' in res) || res.required !== true,
                  isRef: true,
                  encoding: mediaType.encoding,
                })
              : undefined;

            const formUrlEncoded = isFormUrlEncoded
              ? getSchemaFormDataAndUrlEncoded({
                  name: effectivePropName,
                  schemaObject: mediaType.schema,
                  context,
                  isUrlEncoded: true,
                  isRequestBodyOptional:
                    !('required' in res) || res.required !== true,
                  isRef: true,
                  encoding: mediaType.encoding,
                })
              : undefined;

            const additionalImports = getFormDataAdditionalImports({
              schemaObject: mediaType.schema,
              context,
            });
            return {
              ...resolvedValue,
              imports: [...resolvedValue.imports, ...additionalImports],
              formData,
              formUrlEncoded,
              contentType,
              example: mediaType.example,
              examples: resolveExampleRefs(
                mediaType.examples as
                  | Record<string, OpenApiReferenceObject | { value?: unknown }>
                  | undefined,
                context,
              ),
            };
          },
        );

        return contents
          .filter(Boolean)
          .map((x) => ({ ...x, key })) as ResReqTypesValue[];
      }
      const swaggerSchema =
        'schema' in res
          ? (
              res as {
                schema?: OpenApiSchemaObject | OpenApiReferenceObject;
              }
            ).schema
          : undefined;

      if (swaggerSchema) {
        const propName = key
          ? sanitize(pascal(name) + pascal(key), {
              underscore: '_',
              whitespace: '_',
              dash: true,
              es5keyword: true,
              es5IdentifierName: true,
            })
          : undefined;
        const resolvedValue = resolveObject({
          schema: swaggerSchema,
          propName,
          context,
        });

        return [
          {
            ...resolvedValue,
            contentType: 'application/json',
            key,
          },
        ] as ResReqTypesValue[];
      }

      return [
        {
          value: defaultType,
          imports: [],
          schemas: [],
          type: defaultType,
          isEnum: false,
          dependencies: [],
          key,
          isRef: false,
          hasReadonlyProps: false,
          contentType: 'application/json',
        },
      ] as ResReqTypesValue[];
    });

  return uniqueBy(typesArray.flat(), uniqueKey);
}

/**
 * Determine the responseType option based on success content types only.
 * This avoids error-response content types influencing the responseType.
 */
export function getSuccessResponseType(
  response: GetterResponse,
): 'blob' | 'text' | undefined {
  const successContentTypes = response.types.success
    .map((t) => t.contentType)
    .filter(Boolean);

  if (response.isBlob) {
    return 'blob' as const;
  }

  const hasJsonResponse = successContentTypes.some(
    (contentType) =>
      contentType.includes('json') || contentType.includes('+json'),
  );
  const hasTextResponse = successContentTypes.some(
    (contentType) =>
      contentType.startsWith('text/') || contentType.includes('xml'),
  );

  if (!hasJsonResponse && hasTextResponse) {
    return 'text' as const;
  }

  return undefined;
}

/**
 * Get the default content type from a list of content types.
 * Priority: application/json > any JSON-like type > first in list
 *
 * @param contentTypes - Array of content types from OpenAPI spec
 * @returns The default content type to use
 */
export function getDefaultContentType(contentTypes: string[]): string {
  if (contentTypes.length === 0) {
    return 'application/json';
  }

  // Prefer application/json
  if (contentTypes.includes('application/json')) {
    return 'application/json';
  }

  // Prefer any JSON-like type
  const jsonType = contentTypes.find(
    (ct) => ct.includes('+json') || ct.includes('-json'),
  );
  if (jsonType) {
    return jsonType;
  }

  // Default to first
  return contentTypes[0];
}

interface GetFormDataAdditionalImportsOptions {
  schemaObject: OpenApiSchemaObject | OpenApiReferenceObject;
  context: ContextSpec;
}

function getFormDataAdditionalImports({
  schemaObject,
  context,
}: GetFormDataAdditionalImportsOptions): GeneratorImport[] {
  const { schema } = resolveSchemaRef(schemaObject, context);

  if (getSchemaType(schema) !== 'object') {
    return [];
  }

  const combinedSchemas = getSchemaOneOf(schema) ?? getSchemaAnyOf(schema);

  if (!combinedSchemas) {
    return [];
  }

  return combinedSchemas
    .map((subSchema) => resolveSchemaRef(subSchema, context).imports[0])
    .filter(Boolean);
}

interface GetSchemaFormDataAndUrlEncodedOptions {
  name: string;
  schemaObject: OpenApiSchemaObject | OpenApiReferenceObject;
  context: ContextSpec;
  isRequestBodyOptional: boolean;
  isUrlEncoded?: boolean;
  isRef?: boolean;
  encoding?: Record<string, OpenApiEncodingObject>;
}

function getSchemaFormDataAndUrlEncoded({
  name,
  schemaObject,
  context,
  isRequestBodyOptional,
  isUrlEncoded,
  isRef,
  encoding,
}: GetSchemaFormDataAndUrlEncodedOptions): string {
  const { schema, imports } = resolveSchemaRef(schemaObject, context);
  const propName = camel(
    !isRef && !isInlineSchema(schemaObject) ? imports[0].name : name,
  );

  const variableName = isUrlEncoded ? 'formUrlEncoded' : 'formData';
  let form = isUrlEncoded
    ? `const ${variableName} = new URLSearchParams();\n`
    : `const ${variableName} = new FormData();\n`;

  const combinedSchemas = getSchemaCombined(schema);
  const schemaType = getSchemaType(schema);
  if (
    schemaType === 'object' ||
    (schemaType === undefined && combinedSchemas)
  ) {
    if (combinedSchemas) {
      const shouldCast = !!getSchemaOneOf(schema) || !!getSchemaAnyOf(schema);

      if (shouldCast) {
        // If the outer schema also has direct properties, those are handled
        // below by the dedicated properties branch. Skip them here to avoid
        // appending the same key twice. Exclude readOnly direct properties
        // so they can still flow through the runtime loop if a variant
        // declares the same key as writable.
        const directProperties = getSchemaProperties(schema);
        const directKeys = directProperties
          ? Object.entries(directProperties)
              .filter(([, value]) => {
                const resolved = resolveSchemaRef(value, context).schema;
                return isBooleanJsonSchema(resolved) || !resolved.readOnly;
              })
              .map(([key]) => key)
          : [];
        const skipLine =
          directKeys.length > 0
            ? `  if ([${directKeys.map((k) => JSON.stringify(k)).join(', ')}].includes(key)) return;\n`
            : '';

        form += `Object.entries(${propName} ?? {}).forEach(([key, value]) => {\n`;
        form += skipLine;
        form += `  if (value !== undefined && value !== null) {\n`;
        if (isUrlEncoded) {
          // url-encoded: URLSearchParams holds strings only, so File/Blob/
          // Buffer handling does not apply — coerce every value to string (#1624)
          form += `    if (Array.isArray(value)) {\n`;
          form += `      value.forEach(v => {\n`;
          form += `        ${variableName}.append(key, typeof v === 'object' ? JSON.stringify(v) : String(v));\n`;
          form += `      });\n`;
          form += `    } else if (typeof value === 'object') {\n`;
          form += `      ${variableName}.append(key, JSON.stringify(value));\n`;
          form += `    } else {\n`;
          form += `      ${variableName}.append(key, String(value));\n`;
          form += `    }\n`;
        } else {
          form += `    if ((typeof File !== 'undefined' && value instanceof File) || value instanceof Blob) {\n`;
          form += `      ${variableName}.append(key, value);\n`;
          form += `    } else if (typeof Buffer !== 'undefined' && Buffer.isBuffer(value)) {\n`;
          form += `      ${variableName}.append(key, new Blob([Uint8Array.from(value)]));\n`;
          form += `    } else if (Array.isArray(value)) {\n`;
          form += `      value.forEach(v => {\n`;
          form += `        if ((typeof File !== 'undefined' && v instanceof File) || v instanceof Blob) {\n`;
          form += `          ${variableName}.append(key, v);\n`;
          form += `        } else if (typeof Buffer !== 'undefined' && Buffer.isBuffer(v)) {\n`;
          form += `          ${variableName}.append(key, new Blob([Uint8Array.from(v)]));\n`;
          form += `        } else {\n`;
          form += `          ${variableName}.append(key, typeof v === 'object' ? JSON.stringify(v) : String(v));\n`;
          form += `        }\n`;
          form += `      });\n`;
          form += `    } else if (typeof value === 'object') {\n`;
          form += `      ${variableName}.append(key, JSON.stringify(value));\n`;
          form += `    } else {\n`;
          form += `      ${variableName}.append(key, String(value));\n`;
          form += `    }\n`;
        }
        form += `  }\n`;
        form += `});\n`;
      } else {
        const combinedSchemasFormData = combinedSchemas
          .map((subSchema) => {
            const { schema: combinedSchema } = resolveSchemaRef(
              subSchema,
              context,
            );
            return resolveSchemaPropertiesToFormData({
              schema: combinedSchema,
              variableName,
              propName,
              context,
              isRequestBodyOptional,
              encoding,
            });
          })
          .filter(Boolean)
          .join('\n');

        form += combinedSchemasFormData;
      }
    }

    if (getSchemaProperties(schema)) {
      const formDataValues = resolveSchemaPropertiesToFormData({
        schema,
        variableName,
        propName,
        context,
        isRequestBodyOptional,
        encoding,
      });

      form += formDataValues;
    }

    return form;
  }

  if (getSchemaType(schema) === 'array') {
    let valueStr = 'value';
    const schemaItems = getSchemaItems(schema);
    if (schemaItems) {
      const { schema: resolvedItem } = resolveSchemaRef(schemaItems, context);
      const itemSchema = unwrapNullableSchema(resolvedItem, context);
      const itemType = getSchemaType(resolvedItem);
      if (
        isEffectivelyObjectSchema(itemSchema, context) ||
        isEffectivelyArraySchema(itemSchema, context)
      ) {
        valueStr = 'JSON.stringify(value)';
      } else if (
        itemType === 'number' ||
        itemType === 'integer' ||
        itemType === 'boolean'
      ) {
        valueStr = 'value.toString()';
      }
    }

    return `${form}${propName}.forEach(value => ${variableName}.append('data', ${valueStr}))\n`;
  }

  const scalarType = getSchemaType(schema);
  if (
    scalarType === 'number' ||
    scalarType === 'integer' ||
    scalarType === 'boolean'
  ) {
    return `${form}${variableName}.append('data', ${propName}.toString())\n`;
  }

  return `${form}${variableName}.append('data', ${propName})\n`;
}

/**
 * Determines whether a schema is object-shaped once `allOf` composition is
 * resolved, without assuming "has allOf" implies "is an object" (allOf is a
 * generic AND-combinator in JSON Schema and can just as validly compose a
 * constrained string or number). Classifies as object-like only when a
 * resolved branch positively establishes an object shape (own `type:
 * object`, `properties`, `additionalProperties`, or a nested allOf member
 * that itself resolves to an object) — an inconclusive/scalar result never
 * defaults to "object".
 */
export function isEffectivelyObjectSchema(
  schema: OpenApiSchemaObject,
  context: ContextSpec,
  seen: Set<OpenApiSchemaObject> = new Set(),
): boolean {
  if (isBooleanJsonSchema(schema)) {
    return false;
  }
  if (seen.has(schema)) {
    // Recursive schema (e.g. a self-referential allOf chain) — bail out
    // rather than looping; nothing further down this branch can add new
    // information anyway.
    return false;
  }
  seen.add(schema);

  if (
    schema.type === 'object' ||
    (Array.isArray(schema.type) && schema.type.includes('object'))
  ) {
    return true;
  }
  if (schema.properties || schema.additionalProperties) {
    return true;
  }

  const schemaAllOf = schema.allOf;
  if (Array.isArray(schemaAllOf)) {
    return schemaAllOf.some((member) => {
      const { schema: resolved } = resolveSchemaRef(member, context);
      return isEffectivelyObjectSchema(resolved, context, seen);
    });
  }

  return false;
}

/**
 * Array counterpart of {@link isEffectivelyObjectSchema}: `type: array`
 * either on the schema itself or behind its `allOf` members.
 */
function isEffectivelyArraySchema(
  schema: OpenApiSchemaObject,
  context: ContextSpec,
  seen: Set<OpenApiSchemaObject> = new Set(),
): boolean {
  if (isBooleanJsonSchema(schema)) {
    return false;
  }
  if (seen.has(schema)) {
    return false;
  }
  seen.add(schema);

  if (schema.type === 'array') {
    return true;
  }

  const schemaAllOf = schema.allOf;
  return (
    Array.isArray(schemaAllOf) &&
    schemaAllOf.some((member) => {
      const { schema: resolved } = resolveSchemaRef(member, context);
      return isEffectivelyArraySchema(resolved, context, seen);
    })
  );
}

/**
 * The only non-null branch of an `anyOf`/`oneOf` wrapper, e.g.
 * `anyOf: [{ $ref }, { type: 'null' }]`, which is how an OAS 3.0
 * `nullable: true` next to a `$ref` or `allOf` arrives after the upgrade.
 * A schema that is typed or object-shaped on its own is returned as is.
 */
function unwrapNullableSchema(
  schema: OpenApiSchemaObject,
  context: ContextSpec,
): OpenApiSchemaObject {
  if (
    isBooleanJsonSchema(schema) ||
    schema.type !== undefined ||
    isEffectivelyObjectSchema(schema, context)
  ) {
    return schema;
  }

  const branches = (schema.anyOf ?? schema.oneOf ?? [])
    .map((branch) => resolveSchemaRef(branch, context).schema)
    .filter((branch) => !isNullSchema(branch));

  return branches.length === 1 ? branches[0] : schema;
}

/**
 * Collects a schema's own `properties`, merged with any `properties`
 * reachable through `allOf` composition (recursively, following `$ref`s).
 * A pure wrapper schema (`{ allOf: [{ $ref: ... }] }`) has no `properties`
 * of its own — its fields only exist behind the allOf member — so a plain
 * `schema.properties` read misses them entirely.
 */
export function collectPropertiesThroughAllOf(
  schema: OpenApiSchemaObject,
  context: ContextSpec,
  seen: Set<OpenApiSchemaObject> = new Set(),
): Record<string, OpenApiSchemaObject | OpenApiReferenceObject> {
  if (isBooleanJsonSchema(schema)) {
    return {};
  }
  if (seen.has(schema)) {
    return {};
  }
  seen.add(schema);

  const ownProps = getSchemaProperties(schema) ?? {};
  const schemaAllOf = schema.allOf;

  if (!Array.isArray(schemaAllOf)) {
    return ownProps;
  }

  let merged: Record<string, OpenApiSchemaObject | OpenApiReferenceObject> = {};
  for (const member of schemaAllOf) {
    const { schema: resolved } = resolveSchemaRef(member, context);
    merged = {
      ...merged,
      ...collectPropertiesThroughAllOf(resolved, context, seen),
    };
  }
  // Own properties (if any) take precedence over allOf-inherited ones,
  // matching how allOf member conflicts are resolved elsewhere.
  return { ...merged, ...ownProps };
}

/**
 * Same reasoning as {@link collectPropertiesThroughAllOf}, but for
 * `required`: a pure `allOf` wrapper schema has no `required` array of its
 * own, so a plain `schema.required` read loses required-ness for every
 * field that only exists behind the allOf composition.
 */
export function collectRequiredThroughAllOf(
  schema: OpenApiSchemaObject,
  context: ContextSpec,
  seen: Set<OpenApiSchemaObject> = new Set(),
): string[] {
  if (isBooleanJsonSchema(schema)) {
    return [];
  }
  if (seen.has(schema)) {
    return [];
  }
  seen.add(schema);

  const ownRequired = getSchemaRequired(schema) ?? [];
  const schemaAllOf = schema.allOf;

  if (!Array.isArray(schemaAllOf)) {
    return ownRequired;
  }

  const inherited = schemaAllOf.flatMap((member) => {
    const { schema: resolved } = resolveSchemaRef(member, context);
    return collectRequiredThroughAllOf(resolved, context, seen);
  });

  return [...inherited, ...ownRequired];
}

interface ResolveSchemaPropertiesToFormDataOptions {
  schema: OpenApiSchemaObject;
  variableName: string;
  propName: string;
  context: ContextSpec;
  isRequestBodyOptional: boolean;
  keyPrefix?: string;
  depth?: number;
  encoding?: Record<string, OpenApiEncodingObject>;
  // Schemas already being exploded further up, to stop on recursive models.
  ancestors?: Set<OpenApiSchemaObject>;
}

function resolveSchemaPropertiesToFormData({
  schema,
  variableName,
  propName,
  context,
  isRequestBodyOptional,
  keyPrefix = '',
  depth = 0,
  encoding,
  ancestors = new Set(),
}: ResolveSchemaPropertiesToFormDataOptions): string {
  let formDataValues = '';
  const nestedAncestors = new Set(ancestors).add(schema);
  // url-encoded bodies use URLSearchParams (string values only), so file/binary
  // fields are appended as plain strings rather than wrapped in a Blob (#1624).
  const isUrlEncoded = variableName === 'formUrlEncoded';
  const schemaProps = collectPropertiesThroughAllOf(schema, context);
  const propertyConvention =
    // oxlint-disable-next-line typescript/no-unnecessary-condition
    context.output.override.namingConvention?.properties;
  // Same collision set the type renderer computes: keys that would collide
  // after conversion keep their original schema key in the TS type, so the
  // serializer must read those from the original key too (#2381).
  const collisionKeys = getPropertyNameCollisionKeys(
    Object.keys(schemaProps),
    propertyConvention
      ? (name) => conventionName(name, propertyConvention)
      : undefined,
  );
  for (const [key, value] of Object.entries(schemaProps)) {
    const { schema: property } = resolveSchemaRef(value, context);
    if (isBooleanJsonSchema(property)) {
      continue;
    }
    const escapedKey = key
      .replace(/\\/g, '\\\\')
      .replace(/`/g, '\\`')
      .replace(/\$\{/g, '\\${');

    // Skip readOnly properties for formData
    if (property.readOnly) {
      continue;
    }

    let formDataValue = '';

    // Get encoding.contentType for this field (only at top level, depth === 0)
    const fieldEncoding = depth === 0 ? encoding?.[key] : undefined;
    const partContentType = fieldEncoding?.contentType;

    // The TS type emits the namingConvention-converted property name, so the
    // runtime serializer must read the same converted name from the body while
    // still appending the ORIGINAL schema key on the wire (#2381). Colliding
    // keys (e.g. first_name + firstName) keep the original key in the type,
    // so read the original key too.
    const propertyConvention =
      // oxlint-disable-next-line typescript/no-unnecessary-condition
      context.output.override.namingConvention?.properties;
    const accessorKey =
      propertyConvention && !collisionKeys.has(key)
        ? conventionName(key, propertyConvention)
        : key;
    const formattedConvertedKeyPrefix = isRequestBodyOptional
      ? keyword.isIdentifierNameES5(accessorKey)
        ? '?'
        : '?.'
      : '';
    const formattedConvertedKey = keyword.isIdentifierNameES5(accessorKey)
      ? `.${accessorKey}`
      : `[${getKey(accessorKey)}]`;

    const valueKey = `${propName}${formattedConvertedKeyPrefix}${formattedConvertedKey}`;
    const nonOptionalValueKey = `${propName}${formattedConvertedKey}`;

    // Use shared file type detection (same logic as type generation)
    const fileType = getFormDataFieldFileType(property, partContentType);
    const effectiveContentType = partContentType ?? property.contentMediaType;
    // A nullable wrapper is serialized like its non-null branch; the null
    // case is guarded below.
    const valueSchema = unwrapNullableSchema(property, context);
    const valueType = getSchemaType(valueSchema);

    if (isUrlEncoded && (fileType || property.format === 'binary')) {
      // url-encoded: file/binary fields are plain strings (URLSearchParams)
      formDataValue = `${variableName}.append(\`${keyPrefix}${escapedKey}\`, ${nonOptionalValueKey});\n`;
    } else if (fileType === 'binary' || property.format === 'binary') {
      // Binary: append directly (value is Blob)
      formDataValue = `${variableName}.append(\`${keyPrefix}${escapedKey}\`, ${nonOptionalValueKey});\n`;
    } else if (fileType === 'text') {
      // Text file: value is Blob | string, check at runtime
      formDataValue = `${variableName}.append(\`${keyPrefix}${escapedKey}\`, ${nonOptionalValueKey} instanceof Blob ? ${nonOptionalValueKey} : new Blob([${nonOptionalValueKey}], { type: '${jsStringLiteralEscape(
        effectiveContentType ?? '',
      )}' }));\n`;
    } else if (isEffectivelyObjectSchema(valueSchema, context)) {
      // `style: deepObject` + `explode: true` encodes each property as a
      // bracketed key on the parent, e.g. `metadata[order_id]=6735`. This is
      // the default for `deepObject` and is how Swagger/OpenAPI serializers
      // (and the generated runtime) represent nested objects in url-encoded
      // bodies. See orval issue #3803.
      const isDeepObject =
        isUrlEncoded && fieldEncoding?.style === 'deepObject';

      if (isDeepObject) {
        // style: deepObject — emit each property as `key[subkey]=value`
        const inner = `${nonOptionalValueKey} && Object.entries(${nonOptionalValueKey}).forEach(([k, v]) => {
          if (v !== undefined && v !== null) {
            ${variableName}.append(\`${keyPrefix}${escapedKey}[\${k}]\`, typeof v === 'object' ? JSON.stringify(v) : String(v));
          }
        });\n`;
        formDataValue = inner;
      } else {
        formDataValue =
          context.output.override.formData.arrayHandling ===
            FormDataArrayHandling.EXPLODE && !nestedAncestors.has(valueSchema)
            ? resolveSchemaPropertiesToFormData({
                schema: valueSchema,
                variableName,
                propName: nonOptionalValueKey,
                context,
                isRequestBodyOptional,
                keyPrefix: `${keyPrefix}${escapedKey}.`,
                depth: depth + 1,
                encoding,
                ancestors: nestedAncestors,
              })
            : `${variableName}.append(\`${keyPrefix}${escapedKey}\`, JSON.stringify(${nonOptionalValueKey}));\n`;
      }
    } else if (
      valueType === 'array' ||
      (Array.isArray(valueType) && valueType.includes('array'))
    ) {
      let valueStr = 'value';
      let hasNonPrimitiveChild = false;
      const propertyItems = getSchemaItems(valueSchema);
      if (propertyItems) {
        const { schema: resolvedItem } = resolveSchemaRef(
          propertyItems,
          context,
        );
        const itemSchema = unwrapNullableSchema(resolvedItem, context);
        if (
          isEffectivelyObjectSchema(itemSchema, context) ||
          isEffectivelyArraySchema(itemSchema, context)
        ) {
          // Without fields to explode (maps, nested arrays) or on a recursive
          // model, fall back to appending the whole item as JSON.
          const resolvedValue =
            context.output.override.formData.arrayHandling ===
              FormDataArrayHandling.EXPLODE && !nestedAncestors.has(itemSchema)
              ? resolveSchemaPropertiesToFormData({
                  schema: itemSchema,
                  variableName,
                  propName: 'value',
                  context,
                  isRequestBodyOptional,
                  keyPrefix: `${keyPrefix}${escapedKey}[\${index${depth > 0 ? depth : ''}}].`,
                  depth: depth + 1,
                  ancestors: nestedAncestors,
                })
              : '';
          if (resolvedValue) {
            hasNonPrimitiveChild = true;
            const body = isSchemaNullable(resolvedItem)
              ? `if (value !== null && value !== undefined) {\n ${resolvedValue} }\n`
              : resolvedValue;
            formDataValue = `${valueKey}.forEach((value, index${depth > 0 ? depth : ''}) => {
    ${body}});\n`;
          } else {
            valueStr = 'JSON.stringify(value)';
          }
        } else {
          const itemType = getSchemaType(resolvedItem);
          if (
            itemType === 'number' ||
            (Array.isArray(itemType) && itemType.includes('number')) ||
            itemType === 'integer' ||
            (Array.isArray(itemType) && itemType.includes('integer')) ||
            itemType === 'boolean' ||
            (Array.isArray(itemType) && itemType.includes('boolean'))
          ) {
            valueStr = 'value.toString()';
          }
        }
      }
      if (
        context.output.override.formData.arrayHandling ===
        FormDataArrayHandling.EXPLODE
      ) {
        if (!hasNonPrimitiveChild) {
          formDataValue = `${valueKey}.forEach((value, index${depth > 0 ? depth : ''}) => ${variableName}.append(\`${keyPrefix}${escapedKey}[\${index${depth > 0 ? depth : ''}}]\`, ${valueStr}));\n`;
        }
      } else {
        formDataValue = `${valueKey}.forEach(value => ${variableName}.append(\`${keyPrefix}${escapedKey}${context.output.override.formData.arrayHandling === FormDataArrayHandling.SERIALIZE_WITH_BRACKETS ? '[]' : ''}\`, ${valueStr}));\n`;
      }
    } else if (
      (() => {
        const propType = getSchemaType(property);
        return (
          propType === 'number' ||
          (Array.isArray(propType) && propType.includes('number')) ||
          propType === 'integer' ||
          (Array.isArray(propType) && propType.includes('integer')) ||
          propType === 'boolean' ||
          (Array.isArray(propType) && propType.includes('boolean'))
        );
      })()
    ) {
      formDataValue = `${variableName}.append(\`${keyPrefix}${escapedKey}\`, ${nonOptionalValueKey}.toString())\n`;
    } else {
      formDataValue = `${variableName}.append(\`${keyPrefix}${escapedKey}\`, ${nonOptionalValueKey});\n`;
    }

    let existSubSchemaNullable = false;
    const combine = getSchemaCombined(property);
    if (combine) {
      const subSchemas = combine.map((c) =>
        resolveObject({ schema: c, combined: true, context: context }),
      );
      if (
        subSchemas.some((subSchema) => {
          return ['number', 'integer', 'boolean'].includes(subSchema.type);
        })
      ) {
        formDataValue = `${variableName}.append(\`${escapedKey}\`, ${nonOptionalValueKey}.toString())\n`;
      }

      if (
        subSchemas.some((subSchema) => {
          return subSchema.type === 'null';
        })
      ) {
        existSubSchemaNullable = true;
      }
    }

    const schemaRequired = collectRequiredThroughAllOf(schema, context);
    // oxlint-disable-next-line typescript/no-unnecessary-condition
    const isRequired = schemaRequired?.includes(key) && !isRequestBodyOptional;

    const propType = getSchemaType(property);
    if (
      (Array.isArray(propType) && propType.includes('null')) ||
      existSubSchemaNullable
    ) {
      if (isRequired) {
        formDataValues += `if(${valueKey} !== null) {\n ${formDataValue} }\n`;
        continue;
      }

      formDataValues += `if(${valueKey} !== undefined && ${nonOptionalValueKey} !== null) {\n ${formDataValue} }\n`;
      continue;
    }

    if (isRequired) {
      formDataValues += formDataValue;
      continue;
    }

    formDataValues += `if(${valueKey} !== undefined) {\n ${formDataValue} }\n`;
  }

  return formDataValues;
}
