import { resolveObject, resolveRef } from '../resolvers';
import type {
  ContextSpec,
  GeneratorImport,
  GeneratorSchema,
  OpenApiComponentsObject,
  OpenApiParameterObject,
} from '../types';
import { getComponentBaseName, jsDoc, sanitize } from '../utils';

export function generateParameterDefinition(
  parameters: OpenApiComponentsObject['parameters'] = {},
  context: ContextSpec,
  suffix: string,
  prefix = '',
): GeneratorSchema[] {
  if (Object.keys(parameters).length === 0) {
    return [];
  }

  const generatorSchemas: GeneratorSchema[] = [];
  for (const [parameterName, parameter] of Object.entries(parameters)) {
    const modelName = sanitize(
      `${prefix}${getComponentBaseName(parameters, parameterName)}${suffix}`,
      {
        underscore: '_',
        whitespace: '_',
        dash: true,
        es5keyword: true,
        es5IdentifierName: true,
      },
    );
    const {
      schema,
      imports,
    }: {
      schema: OpenApiParameterObject;
      imports: GeneratorImport[];
    } = resolveRef(parameter, context);

    if (schema.in !== 'query' && schema.in !== 'header') {
      continue;
    }

    if (!('schema' in schema) || !schema.schema || imports.length > 0) {
      generatorSchemas.push({
        name: modelName,
        imports:
          imports.length > 0
            ? [
                {
                  name: imports[0].name,
                  schemaName: imports[0].schemaName,
                },
              ]
            : [],
        model: `export type ${modelName} = ${
          imports.length > 0 ? imports[0].name : 'unknown'
        };\n`,
        dependencies: imports.length > 0 ? [imports[0].name] : [],
        kind: 'schema',
      });

      continue;
    }

    const resolvedObject = resolveObject({
      schema: schema.schema,
      propName: modelName,
      context,
    });

    const doc = jsDoc(schema);

    const model = `${doc}export type ${modelName} = ${
      resolvedObject.value || 'unknown'
    };\n`;

    generatorSchemas.push(...resolvedObject.schemas);

    if (modelName !== resolvedObject.value) {
      generatorSchemas.push({
        name: modelName,
        model,
        imports: resolvedObject.imports,
        dependencies: resolvedObject.dependencies,
        kind: 'schema',
      });
    }
  }

  return generatorSchemas;
}
